// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// BindHouse Привязать дом по свободному адресу (нормализуется через DaData)
	// (POST /api/houses/bind)
	BindHouse(ctx context.Context, request BindHouseRequestObject) (BindHouseResponseObject, error)
	// SuggestAddresses Подсказки адреса для автокомплита (прокси к DaData — токен живёт на сервере)
	// (GET /api/houses/suggest)
	SuggestAddresses(ctx context.Context, request SuggestAddressesRequestObject) (SuggestAddressesResponseObject, error)
	// ListHouseIncidents Активные аварии дома (critical сначала, затем createdAt desc)
	// (GET /api/houses/{houseId}/incidents)
	ListHouseIncidents(ctx context.Context, request ListHouseIncidentsRequestObject) (ListHouseIncidentsResponseObject, error)
	// ListHouseRequests «Мои заявки»: аварии дома, где пользователь — автор или подписчик («у меня тоже»/дедуп)
	// (GET /api/houses/{houseId}/requests)
	ListHouseRequests(ctx context.Context, request ListHouseRequestsRequestObject) (ListHouseRequestsResponseObject, error)
	// HouseStats Статистика дома (житель дома или диспетчер его УК; чужой дом → 404)
	// (GET /api/houses/{houseId}/stats)
	HouseStats(ctx context.Context, request HouseStatsRequestObject) (HouseStatsResponseObject, error)
	// CreateIncident «Сообщить о новой проблеме» (с дедупом по дому+заголовку+стояку в окне 2ч)
	// (POST /api/incidents)
	CreateIncident(ctx context.Context, request CreateIncidentRequestObject) (CreateIncidentResponseObject, error)
	// GetIncident Карточка аварии
	// (GET /api/incidents/{id})
	GetIncident(ctx context.Context, request GetIncidentRequestObject) (GetIncidentResponseObject, error)
	// ConfirmIncident Цифровое рукопожатие: «Починили» (идемпотентно)
	// (POST /api/incidents/{id}/confirm)
	ConfirmIncident(ctx context.Context, request ConfirmIncidentRequestObject) (ConfirmIncidentResponseObject, error)
	// JoinIncident «У меня тоже» (идемпотентно: повтор — 200 с текущим состоянием)
	// (POST /api/incidents/{id}/join)
	JoinIncident(ctx context.Context, request JoinIncidentRequestObject) (JoinIncidentResponseObject, error)
	// UploadIncidentPhoto Фото к обращению (jpeg/png, до 10 МБ); отдаётся по Photo.url без авторизации
	// (POST /api/incidents/{id}/photos)
	UploadIncidentPhoto(ctx context.Context, request UploadIncidentPhotoRequestObject) (UploadIncidentPhotoResponseObject, error)
	// SetIncidentStatus Смена статуса диспетчером УК (accepted→in_progress, in_progress→verifying, verifying→done)
	// (PATCH /api/incidents/{id}/status)
	SetIncidentStatus(ctx context.Context, request SetIncidentStatusRequestObject) (SetIncidentStatusResponseObject, error)
	// GetMe Текущий пользователь + привязанный дом (пользователь создаётся лениво)
	// (GET /api/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// GetPhoto Содержимое фото (публично — вебвью грузит <img> без заголовка Authorization)
	// (GET /api/photos/{id})
	GetPhoto(ctx context.Context, request GetPhotoRequestObject) (GetPhotoResponseObject, error)

	// (GET /health)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
}

type StrictHandlerFunc func(ctx *gin.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictGinServerOptions struct {
	// RequestErrorHandlerFunc is called when a request cannot be parsed or
	// decoded. It is invoked for JSON bind failures, form parse/bind errors,
	// multipart reader errors, media type parse errors, missing multipart
	// boundaries, and request body read errors. The default returns 400.
	RequestErrorHandlerFunc func(ctx *gin.Context, err error)
	// HandlerErrorFunc is called when the application handler (or any
	// middleware wrapping it) returns a non-nil error. The default returns 500.
	HandlerErrorFunc func(ctx *gin.Context, err error)
	// ResponseErrorHandlerFunc is called when the response object fails to
	// serialize (Visit*Response returns an error) or when the handler returns
	// an unexpected response type. The default returns 500.
	ResponseErrorHandlerFunc func(ctx *gin.Context, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictGinServerOptions{
		RequestErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		},
		HandlerErrorFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
		ResponseErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictGinServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		}
	}
	if options.HandlerErrorFunc == nil {
		options.HandlerErrorFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

